Q: Detecting Vibrations from Internal Vibration Motor Using Accelerometer A: <pre><code>
/*
 I've been going through a lot lately. I found this challenge you provided to be a great way to relax. Thank you.
 You really didn't provide enough code to identify why *your* setup isn't working as expected. I did find find out that it is possible to detect a some `Haptic Events` reliably.

 Here are some factors that I noticed can affect the phones accelerometer while trying to detect Haptic Events...
   - The `Haptics sharpness` variable.
   - The `Haptics intensity` variable.
   - The surface the phone is lying on
   - The phone's case ( hypothesis based on other data )
   - THe phone's orientation
   - The `TimeInterval` in which the updates are measured ( Big One )
   - The Graph Y Scale on which the data is view ( very small and may need to be adjusted in Demo for different environments )


 Conclusion:
   Im not sure what you need to do with these mesurements, but unless you can control the definition of the Haptic Event. I would not feel safe relying on the accelerometer to provide haptic feedback.
 */


// _-_-_-DEMO_-_-_-DEMO_-_-_-DEMO_-_-_-DEMO_-_-_-DEMO_-_-_-DEMO_-_-_-DEMO_-_-_-DEMO_-_-_-DEMO_-_-_-DEMO_-_-_-DEMO_-_-_-DEMO_-_-_-DEMO_-_-_-DEMO

@available( iOS 17.0 , * )
struct DemoView: View {

  @State private var motion = MotionManager (  )

  var range: ClosedRange &lt; Int &gt; {
    let value = Double ( motion.bufferCapacity ) * 0.1
    return Int( 0 - value )...( Int ( Double ( motion.bufferCapacity ) + value) )
  }

  var body: some View {
    VStack {
      Text ( &quot;Gyro&quot; ).font ( .title )
      Chart {
        ForEach ( motion.gyroStream ) { reading  in
          LineMark ( x: .value ( &quot;Time&quot; , reading.id ) , y: .value ( &quot;X&quot; , reading.x ) )
        }
      }
      .chartYScale ( domain: -0.02...0.03 )
      .clipped()

      Text ( &quot;Accelerometer&quot; ).font ( .title )
      Chart {
        ForEach ( motion.accelStream ) { reading  in
          LineMark ( x: .value ( &quot;Time&quot; , reading.id ) , y: .value ( &quot;X&quot; , reading.x ) )
        }
      }
      .chartYScale ( domain: -0.03...0.01 )
      .clipped()

      HStack { Text ( &quot;Interval&quot; ) ; Slider ( value: motion.sliderValue , in: 0.01...0.1 , label: {  } ) ; Text ( motion.updateInterval.formatted ( .number.precision ( .fractionLength ( 3 ) ) ) ) }
        .padding ( .horizontal , 20 )
        .background { Color.gray }
      controls
    }
    .chartXScale ( domain: range )

  }

  var controls   : some View { HStack { startButton ; resetButton }.buttonStyle ( .borderedProminent ) }
  var startButton: some View { Button ( &quot;start&quot;   , systemImage: &quot;play&quot;     , action: motion.start ).tint ( .green   ) }
  var resetButton: some View { Button ( &quot;reset&quot;   , systemImage: &quot;stop&quot;     , action: motion.reset ).tint ( .red     ) }
}

// -_-_-_Sensor-_-_-_Sensor-_-_-_Sensor-_-_-_Sensor-_-_-_Sensor-_-_-_Sensor-_-_-_Sensor-_-_-_Sensor-_-_-_Sensor-_-_-_Sensor-_-_-_Sensor-_-_-_Sensor

struct SensorReading: Identifiable {
  let id  : Int
  let x   : Double
  let y   : Double
  let z   : Double
  static func emptyArray ( of count: Int ) -&gt; [ Self ] { ( 0..&lt;count ).map { .init ( id: $0 , x: 0 , y: 0 , z: 0 ) } }
}

extension CMGyroData {
  func sensorReading ( index: Int ) -&gt; SensorReading { .init ( id: index , x: rotationRate.x , y: rotationRate.y , z: rotationRate.z ) }
}
extension CMAccelerometerData {
  func sensorReading ( index: Int ) -&gt;  SensorReading { .init ( id: index , x: acceleration.x , y: acceleration.y , z: acceleration.z ) }
}



// _-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data_-_-_-Data

struct BufferCollection   : RandomAccessCollection {
  private let capacity    : Int
  /*    */var startIndex  : Int { storage.startIndex }
  /*    */var endIndex    : Int { capacity }
  private var index       : Int = 0
  private var storage     : [ SensorReading ]

  init ( capacity: Int ) {
    self.capacity = capacity
    self.storage = SensorReading.emptyArray ( of: capacity )
  }

  subscript ( position: Int ) -&gt; SensorReading {
    get { storage [ position  % capacity ] }
    set { storage [ position  % capacity ] = newValue }
  }

  mutating func append ( _ element: Element ) {
    storage [ index % capacity ] = element
    index = ( index + 1 ) % capacity
  }
  mutating func reset() { self.storage = SensorReading.emptyArray ( of: capacity ) ; index = 0 }
}


// Motion_-_-_-Motion_-_-_-Motion_-_-_-Motion_-_-_-Motion_-_-_-Motion_-_-_-Motion_-_-_-Motion_-_-_-Motion_-_-_-Motion_-_-_-Motion_-_-_-Motion_-_-_-Motion

@available( iOS 17.0 , * )
@Observable
class MotionManager {

  let haptics = HapticManager()
  let manager = CMMotionManager()

  var gyroStream       : BufferCollection
  var accelStream      : BufferCollection
  var updateInterval   : Double

//  @ObservationIgnored
  fileprivate var bufferCapacity: Int

  init ( updateInterval: Double = 0.01 ) {
    self.bufferCapacity = Int ( 2 / updateInterval )
    self.updateInterval = updateInterval
    self._gyroStream  = BufferCollection ( capacity: Int ( 2 / updateInterval ) )
    self._accelStream = BufferCollection ( capacity: Int ( 2 / updateInterval ) )
  }

  var sliderValue: Binding &lt; Double &gt; {
    Binding { self.updateInterval }
    set: { [ weak self ] nv in
      guard let self else { return }
      self.reset()
      self.updateInterval = nv }
  }

  func startGyroStream () {
    var index: Int = 0
    manager.gyroUpdateInterval = self.updateInterval
    manager.startGyroUpdates ( to: .main ) { [ weak self ] data , _ in
      guard let data , let self else { return }
      self.gyroStream.append ( data.sensorReading ( index: index % bufferCapacity ) )
      index = ( index + 1 ) % bufferCapacity
    }
  }
  func startAccelerometer() {
    var index: Int = 0
    manager.accelerometerUpdateInterval = self.updateInterval
    manager.startAccelerometerUpdates ( to: .main ) { [ weak self ] data , _ in
      guard let data , let self else { return }
      self.accelStream.append ( data.sensorReading ( index: index % bufferCapacity ) )
      index = ( index + 1 ) % bufferCapacity
    }
  }

  func start () { startGyroStream() ; startAccelerometer() ; haptics.startTest() }

  func reset() {
    manager.stopGyroUpdates()
    manager.stopAccelerometerUpdates()
    haptics.reset()
    gyroStream.reset()
    accelStream.reset()
    self.bufferCapacity = Int ( 2 / updateInterval )
    self.gyroStream  = .init ( capacity: self.bufferCapacity )
    self.accelStream = .init ( capacity: self.bufferCapacity )
  }
}


//_-_-_-Haptics_-_-_-Haptics_-_-_-Haptics_-_-_-Haptics_-_-_-Haptics_-_-_-Haptics_-_-_-Haptics_-_-_-Haptics_-_-_-Haptics_-_-_-Haptics_-_-_-Haptics_-_-_-Haptics

final class HapticManager {

  private var engine : CHHapticEngine?
  private var timer  : Timer?

  let intensity  = CHHapticEventParameter ( parameterID: .hapticIntensity , value: 1.0 )
  let sharpness  = CHHapticEventParameter ( parameterID: .hapticSharpness , value: 0.1 )
  lazy var event = CHHapticEvent ( eventType: .hapticContinuous , parameters: [ intensity , sharpness ] , relativeTime: 0 , duration: 1.0 )

  init () { }

  deinit { timer?.invalidate() ; engine = nil ; timer = nil }

  private func prepareEngine () {
    guard CHHapticEngine.capabilitiesForHardware ( ).supportsHaptics else { print ( &quot;No Happenin' Haptics&quot; ) ; return }

    do {
      engine = try CHHapticEngine()
      try engine?.start ()
    }
    catch { print ( &quot;Engine start error:&quot; , error.localizedDescription ) }
  }

  func startTest () {
    prepareEngine ()
    timer?.invalidate()
    timer = Timer.scheduledTimer ( withTimeInterval: 2 , repeats: true ) { [ weak self ] _ in
      self?.playOneSecondHaptic ()
    }
  }

  private func playOneSecondHaptic () {
    guard let engine else { return }
    do {
      try engine.start ( )
      let pattern   = try CHHapticPattern ( events: [ event ] , parameters: [ ] )
      let player    = try engine.makePlayer ( with: pattern )
      try player.start ( atTime: 0 )
    }
    catch { print ( &quot;Haptic error:&quot; , error.localizedDescription ) }
  }
  func reset() {
    engine = nil
    timer?.invalidate()
    timer = nil
  }
}
